def min_covering_window(values, required):
    if not required:
        return [0, 0]

    req_counts = {}
    for r in required:
        req_counts[r] = req_counts.get(r, 0) + 1

    need = len(req_counts)
    have = 0
    window_counts = {}
    left = 0
    best_len = float('inf')
    best = None

    for right, val in enumerate(values):
        if val in req_counts:
            window_counts[val] = window_counts.get(val, 0) + 1
            if window_counts[val] == req_counts[val]:
                have += 1

        while have == need:
            cur_len = right - left + 1
            if cur_len < best_len:
                best_len = cur_len
                best = [left, right + 1]

            left_val = values[left]
            if left_val in req_counts:
                if window_counts[left_val] == req_counts[left_val]:
                    have -= 1
                window_counts[left_val] -= 1
            left += 1

    return best

